#!/usr/bin/env python3
from pathlib import Path
import importlib.util,html,re,json
ROOT=Path(__file__).resolve().parents[1];TARGET=ROOT/'clase-bigquery'
spec=importlib.util.spec_from_file_location('clase_bigquery',TARGET/'guion.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
E=html.escape
rendered=[]
for i,s in enumerate(m.SLIDES,1):
 title='' if 'cover' in s['layout'].split() else f'<h1>{s["title"]}</h1>'
 cls=' '.join(x if x in ('cover','dark','statement') else 'kind-'+x for x in s['layout'].split())
 rendered.append(f'<section class="slide {cls}" data-id="BQ-{i:02}" data-title="{E(s["title"],quote=True)}" data-note="{E(s["note"],quote=True)}"><div class="eyebrow"><span>Clase independiente · {s["phase"]}</span><span>Chema Sarmiento</span></div>{title}<div class="content">{s["body"]}</div><div class="source"><span>{s["source"]}</span><span>{i:02} / {len(m.SLIDES)}</span></div></section>')
# Reutiliza el shell probado del curso, conservando la fuente de esta clase separada.
page=(ROOT/'especialidad-01/index.html').read_text()
page=re.sub(r'<title>.*?</title>','<title>BigQuery, arquitectura y Medallion · Clase ejecutiva</title>',page,count=1)
page=re.sub(r'<meta name="description"[^>]+>','<meta name="description" content="Clase autónoma de tres horas: BigQuery, arquitecturas, Medallion y laboratorio con muestra real de all_data.csv.">',page,count=1)
page=re.sub(r'(<main id="stage"[^>]*>).*?(</main>)',lambda x:x[1]+''.join(rendered)+x[2],page,count=1,flags=re.S)
page=page.replace('data-session="1"','data-session="bigquery"').replace('Ruta de la sesión 1','Ruta de la clase').replace('Laboratorio · sesión 1','Laboratorio · all_data.csv')
page=page.replace('</head>','<link rel="stylesheet" href="estilos.css"><script src="interacciones.js" defer></script></head>')
(TARGET/'index.html').write_text(page)
(TARGET/'notas-docente.md').write_text('# BigQuery, arquitectura y Medallion · 180 minutos\n\nFuente: guion.py. Los conteos son de la muestra; ejecución GoogleSQL en GCP pendiente.\n\n'+'\n\n'.join(f'## {i:02}. {s["title"]}\n\n{s["note"]}' for i,s in enumerate(m.SLIDES,1))+'\n')
(TARGET/'manifest.json').write_text(json.dumps({'title':'BigQuery, arquitectura y Medallion','minutes':180,'slides':len(m.SLIDES),'sample_rows':4500,'source':'guion.py','cloud_tested':False},ensure_ascii=False,indent=2)+'\n')
def link(f):return f'<a href="recursos/{f}" download>{f} ↓</a>'
def shell(title,body):return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../compartido/curso.css"><link rel="stylesheet" href="guia.css"></head><body><article class="guide"><a href="index.html">← Presentación</a><h1>{title}</h1>{body}</article></body></html>'
steps=[
('Preparar proyecto y cargar muestra',15,'00_preparar.sql',
'''En Google Cloud, selecciona el proyecto autorizado del taller y abre BigQuery → Studio → editor SQL (consulta nueva). Ejecuta 00_preparar.sql. Verás emergente_bronze, emergente_silver y emergente_gold. Región propuesta us-central1; si tu organización usa otra, cambia las tres antes de crearlas. El plazo de siete días solo se aplica a tablas nuevas de estos datasets; verifica la expiración si ya existían.
Descarga all_data_muestra.csv y esquema-bronze.json. En Explorador abre emergente_bronze → Crear tabla. Fuente: Subir archivo; formato CSV; destino: entrada. Desactiva autodetección, usa las 15 columnas STRING del esquema, omite1 fila de cabecera, UTF-8, separador coma y comillas dobles; admite saltos de línea entre comillas. Errores permitidos: 0. En preferencias de escritura selecciona sobrescribir SOLO entrada, que es la zona temporal de carga. Si la UI no permite este flujo sobre la tabla existente, usa cargar-muestra.sh en Cloud Shell con los dos archivos pequeños.
Ejecuta SELECT COUNT(*) AS filas FROM emergente_bronze.entrada;''',
'4500 filas. Abre Vista previa y verifica producto, precio y fechaRegistro. Esto aún no aplica reglas de Silver.',
'Permiso o facturación: pedir al responsable el acceso al proyecto. No otorgar Owner indiscriminadamente. Error CSV: revisar codificación, cabecera, esquema y quote; no aumentar max_bad_records para ocultarlo.'),
('Conservar Bronze por lote',10,'01_ingestar_bronze.sql',
'''Abre una consulta nueva. Ejecuta el archivo completo con lote all_data_muestra_v1. Conserva el ID de trabajo. Observa los valores originales, lote_id, fuente_uri, ingestado_en y fila_hash. No modifiques el archivo ni elimines espacios aquí. Repite el mismo script para comprobar que ASSERT detiene una segunda ingesta con ese ID.
El original en GCS o el CSV descargado conserva sus bytes; la tabla representa registros, no el archivo binario. La protección de lotes presupone ejecución serial en un proyecto dedicado.''',
'Primer lote:4500 filas y 4500 hashes distintos. Segunda ejecución con el mismo ID: error esperado, total sin cambios.',
'Si el lote ya existía por una sesión anterior, inspecciónalo antes de decidir. Usa un ID diferente solo para una entrega distinta, no para esquivar la comprobación.'),
('Perfilar el contenido recibido',10,'02_perfil.sql',
'''Ejecuta cada SELECT de 02. Contrasta los resultados con perfil-muestra.json. El segundo SELECT encuentraREFRESCO/SPRITE/BOTELLA2LT.NO RETORNABLE, Tlalpan,2014-03-19. Copia las filas con dirección y establecimiento antes de formular conclusiones.
La muestra selecciona 1500 filas de cada una de tres ventanas de 2 MiB; no es aleatoria. El rango observado de fechas y las proporciones no representan todo all_data.csv.''',
'4500 filas; 3000 municipios con espacios finales; 0 duplicados exactos en la muestra. Precios del par:15.10 y15.50MXN.',
'Un conteo distinto exige revisar archivo y lote. No atribuyas al archivo completo un resultado obtenido de la muestra.'),
('Construir Silver y reconciliar',15,'03_silver.sql',
'''Ejecuta 03 completo. Normaliza espacios y mayúsculas, convierte precio a NUMERIC y fechaRegistro a DATETIME sin zona; deriva DATE. Deduplica filas exactamente iguales según firma de15 campos de entrada, aun si llegaron en lotes distintos. Los rechazos conservan motivo y referencia a Bronze.
Se crean precios (partición mensual y clustering), rechazadas, control y precios_plana para el benchmark. Toda consulta a precios debe filtrar fecha. Esta versión reconstruye Silver desde todo Bronze: es simple y reproducible; no es incremental.
Las claves producto_id y tienda_id son derivadas de textos. No sonIDs oficiales y no resuelven por sí solas cambios de dirección, marcas S/M o nombres históricos.''',
'Consulta control: entrada = duplicadas_exactas + aceptadas + rechazadas. En esta muestra,4500 aceptadas y0 rechazadas; no fabricar rechazos para llenar una tabla.',
'Error por filtro requerido: añadir WHERE fecha BETWEEN ... sobre la columna de partición. No quitar la protección por comodidad. Conversión fallida: revisar rechazadas y el campo original enBronze.'),
('Preparar Gold para comparar',10,'04_gold.sql',
'''Ejecuta 04 con inicio2011-01-01 y fin2015-12-31 para la muestra. Precio_tienda_dia conserva un grano deproducto/marca/presentación/tienda/día. Dos precios distintos en ese grupo dejan precio_comparable_mxn enNULL y un conflicto visible. Comparacion resume por producto/día/estado/municipio; conserva conteos de tiendas comparables y conflictivas.
Abre el resultado del filtro final y revisa ambas tablas. No tratar S/M como equivalencia comercial demostrada. No usarSUM(precio) como ventas ni inferir inventario.''',
'ParSPRITE de la muestra:2 tiendas comparables, menor 15.10, mayor 15.50, diferencia 0.40MXN. Comparación histórica entre tiendas observadas; no recomendación actual.',
'Sin filas: comprobar las fechas y etiquetas del filtro. Al usar el archivo completo, determinar su cobertura antes de cambiar inicio/fin; el rango de la muestra no certifica la cobertura global.'),
('Medir optimización sin cambiar la pregunta',10,'05_optimizar.sql',
'''Abre 05 y ejecuta sus SELECT uno por uno. En ajustes de consulta, desmarca usar resultados almacenados en caché. Para consultas bajo modalidad bajo demanda, configura Maximum bytes billed/Bytes máximos facturados:1073741824(1GiB) como límite inicial de la muestra; si el validador lo supera, detén y revisa en vez de quitarlo. Este límite no cubre almacenamiento y no sustituye las alertas.
A usaSilver plana; B usaSilver particionada/clusterizada con el mismo filtro y columnas. Compara resultados antes de bytes. C leeGold ya materializada y solo es equivalente a MIN cuando no hay conflictos en esa selección.
Abre Información del trabajo / Job information: anota job_id, bytes procesados y facturados, cache_hit, duración y estimación previa en registro-optimizacion.csv. El clustering puede podar bloques al ejecutar; la estimación previa puede ser superior. En una muestra pequeña, mínimos de facturación pueden esconder diferencias. Los scripts con DDL y varias sentencias no siempre se estiman completos con dry run; ensayarlos aparte antes de usar20.7 GB.''',
'A yB devuelven el mismo par de precios. Registra medidas reales, incluso si el ahorro es0. No convertir bytes del CSV en una factura de consulta.',
'Si cache_hit estrue, el tiempo no sirve para atribuir la mejora a particiones. Si A/B difieren, corregir filtros o datos antes de comparar rendimiento. No ampliar el límite de facturación sin revisar el estimado.'),
('Validar y cerrar',10,'06_validar.sql',
'''Ejecuta 06. Guarda los controles y la comparación simétrica de A/B. Descarga el resultado y tu registro. Después de guardar el benchmark,07_cierre.sql elimina exclusivamente precios_plana.
Revisa expiraciones con el docente. No borres Bronze o el proyecto compartido: se necesitan para la tarea. Cerrar el navegador no elimina tablas ni detiene servicios.''',
'La diferencia simétrica A/B devuelve 0 filas. Entrega evidencia del trabajo y explica qué queda pendiente de ejecutar.',
'Si no tuviste acceso a GCP, entrega la revisión de consultas y el perfil local etiquetados como tal; no presentes job_ids o métricas inventados.')]
intro='''<p class="notice">Clase ejecutiva independiente ·180 minutos. Laboratorio80 minutos. Muestra real derivada del Drive del usuario, no datos ficticios. Los SQL están preparados para GoogleSQL; la ejecución real en BigQuery sigue pendiente de ensayo docente.</p><h2>Antes de clase</h2><p>Proyecto de laboratorio con facturación y permisos aprobados: crear datasets/tablas y ejecutar jobs. No se garantiza elegibilidad de losUS$300 ni acceso por tener cuentaGoogle. Datos y cómputo deben usar ubicación compatible. No hacen faltaVM, Spark, modelos ni despliegue de aplicaciones. Confirmar región, presupuesto, cuotas y expiración. El docente debe ensayar todos los scripts y el archivo completo antes de impartir.</p><p>Elige ruta: muestra de 4500 filas para ejecutar de principio a fin durante clase; archivo completo previamente preparado en GCS para demostración de escala. No descargar20.7 GB en laptops o almacenamiento persistente deCloud Shell durante el taller.</p><h2>Descargas</h2>'''
files=sorted(p.name for p in (TARGET/'recursos').iterdir() if p.is_file())
body=intro+'<ul>'+''.join(f'<li>{link(f)}</li>' for f in files)+'</ul>'
for n,(title,minutes,f,action,check,recover) in enumerate(steps,1):
 body+=f'<section id="paso-{n}"><h2>Paso {n} · {title} · {minutes} min</h2>'+''.join(f'<p>{E(t)}</p>' for t in action.split('\n'))+f'<p><strong>Comprobación:</strong> {E(check)}</p><p><strong>Si falla:</strong> {E(recover)}</p><p>{link(f)}</p><details><summary>Consulta completa</summary><pre><code>{E((TARGET/"recursos"/f).read_text())}</code></pre></details></section>'
body+='''<h2>Ruta docente para el archivo completo</h2><p>Conservar el original en un bucket autorizado, con nombre deobjeto, tamaño, generación/checksum y manifiesto. Transferir desde una estación o entorno con espacio suficiente; no usar el disco limitado deCloud Shell. Ejecutar cargar-gcs.sh con una URIgs:// concreta ya preparada. Se escribe solo emergente_bronze.entrada. Antes de01, cambiar lote y fuente a los del archivo completo. Perfilar02 y verificar fechas antes de reconstruir Silver/Gold. Ejecutar una vez, guardar controles y usar tablas preparadas en clase. El diseño no presupone que la muestra valide todas las filas del archivo.</p><p>La duplicación plana solo sirve para el benchmark y puede costar almacenamiento. Para producción decidir retención, actualización por lotes nuevos y recálculo de particiones afectadas; conservar controles de llegadas tardías y conflictos. Una tabla Gold pequeña no sale gratis: hay que construirla y mantenerla.</p><h2>Fuentes</h2><p>Consulta2026-11-09: <a href="https://docs.cloud.google.com/bigquery/docs/running-queries">ejecutar consultas</a>, <a href="https://docs.cloud.google.com/bigquery/docs/best-practices-costs">control de costos</a>, <a href="https://docs.cloud.google.com/bigquery/docs/partitioned-tables">particiones</a> y <a href="https://cloud.google.com/discover/what-is-a-data-lakehouse">lakehouse</a>.</p><p><a href="tarea.html">Tarea de actualización →</a></p>'''
(TARGET/'laboratorio.html').write_text(shell('Laboratorio · all_data.csv en BigQuery',body))
task='''<p>Objetivo: incorporar un corte adicional de QQP y demostrar qué cambió sin perder el histórico. La actualización es posterior a la clase. No publicar una recomendación actual a partir de fechas históricas.</p><ol><li>Localiza un archivo acotado en el <a href="https://datos.profeco.gob.mx/">catálogo oficial PROFECO</a>. Registra URL, periodo, fecha de descarga, licencia/condiciones, tamaño y checksum. Conserva el original. No se ha validado aquí el esquema de la entrega nueva.</li><li>Abre su cabecera y documenta el mapa a las 15 columnas del taller. Comprueba delimitador, codificación, tipos, unidades y formato de fecha. Ejemplos condicionales: fecha_registro→fechaRegistro; cadena_comercial→cadenaComercial. No inventes campos ausentes ni conviertas marca S/M en una identidad cierta. Si el contrato no encaja, explica qué adaptación requiere.</li><li>Carga la entrega adaptada en entrada con sobrescritura solo de esa tabla. Conserva all_data y todos los lotes Bronze. Ejecuta 01 con un nuevo lote_id y fuente_uri. La ruta es serial; no ejecutar dos ingestas concurrentes.</li><li>Perfila el nuevo lote modificando el filtro de 02. Guarda conteos, fechas y conversiones. Ejecuta 03 para reconstruir Silver y04 con el periodo que quieras comparar. Esta ruta releeBronze completo: medir su costo, no llamarla incremental.</li><li>Prueba idempotencia: el mismo ID de lote se rechaza; repetir las mismas filas en un lote de prueba distinto no debe aumentar las firmas únicas deSilver. Bronze sí registra las filas recibidas. Un precio corregido tiene firma distinta y debe permanecer trazable; si contradice otro del mismo grupo/día,Gold muestra conflicto.</li><li>Propón una optimización incremental: procesar lotes nuevos, deduplicar contra firmas existentes y recalcular únicamente particiones y agregados afectados. Incluye llegadas tardías, correcciones, cambios de esquema y conciliación. No necesitas implementar un MERGE genérico sin contrato.</li><li>Compara un producto realmente equivalente entre periodos, explicando cambios de población, marca, presentación ytienda. No etiquetes esa diferencia como inflación oficial ni ahorro realizable.</li></ol><h2>Entrega</h2><p>Manifiesto del lote y mapa de columnas; SQL ejecutado; conteosBronze/Silver/Gold antes/después; prueba de repetición; conflictos y tratamiento; jobs/bytes reales; recomendación ejecutiva de una página y arquitectura elegida.</p><h2>Criterios ·100 puntos</h2><ul><li>20: procedencia y contrato del lote.</li><li>30: calidad, reconciliación y repetición comprobada.</li><li>20:Gold y comparación con grano explícito.</li><li>20: medición de costo y propuesta de optimización.</li><li>10: decisión y límites comprensibles.</li></ul><p>Si falta acceso al motor, registra ejecución pendiente y presenta la revisión técnica; no sustituye evidencia de ejecución. Consulta <a href="laboratorio.html">la guía</a> y conserva los recursos según retención acordada.</p>'''
(TARGET/'tarea.html').write_text(shell('Tarea · incorporar una entrega nueva sin perder historia',task))
print(f'Clase BigQuery: {len(m.SLIDES)} slides,180 min; laboratorio80 min y tarea independiente.')
